package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

const StickyAffinityBonus = 250.0
const unknownUtilizationPenalty = 0.0
const unknownPerformancePenalty = 0.0

// scorePolicy returns a score for a candidate under the named profile.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - standard: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is profile-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(profile string, cand candidateInternal) float64 {
	total := 0.0
	for _, component := range scoreComponents(profile, cand) {
		total += component
	}
	return total
}

func scoreComponents(profile string, cand candidateInternal) map[string]float64 {
	components := map[string]float64{
		"base": 100,
	}
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK
	add := func(name string, value float64) {
		if value == 0 {
			return
		}
		components[name] += value
	}

	switch profile {
	case "cheap":
		if cand.CostClass == "local" {
			base += 40
			add("deployment_locality", 40)
		} else if withinQuota {
			base += 20
			add("quota_health", 20)
		}
		base -= float64(cr) * 30
		add("cost", -float64(cr)*30)

	case "standard":
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)

	case "smart":
		// Quality first; higher cost rank approximates higher capability.
		base += float64(cr) * 20
		add("cost", float64(cr)*20)
		if withinQuota {
			base += 5
			add("quota_health", 5)
		}

	default:
		// Treat unspecified as standard.
		if cand.CostClass == "local" {
			base += 25
			add("deployment_locality", 25)
		} else if withinQuota {
			base += 15
			add("quota_health", 15)
		}
		base -= float64(cr) * 10
		add("cost", -float64(cr)*10)
	}

	// Provider preference bias.
	switch cand.ProviderPreference {
	case "local-first", "":
		if cand.CostClass == "local" {
			base += 30
			add("deployment_locality", 30)
		}
	case "subscription-first":
		if cand.IsSubscription && cand.QuotaOK {
			base += 30
			add("quota_health", 30)
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
			add("quota_health", -15)
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
			add("quota_health", -40)
		case "burning":
			base -= 20
			add("quota_health", -20)
		case "healthy":
			base += 10
			add("quota_health", 10)
		}

		// Quota near-limit penalty (>= 80% used).
		if cand.QuotaPercentUsed >= 80 {
			penalty := float64(cand.QuotaPercentUsed-80) * 2
			base -= penalty
			add("quota_health", -penalty)
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
			add("quota_health", 20)
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
			add("quota_health", -30)
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
			add("quota_health", 25)
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
			add("quota_health", -35)
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
		add("quota_health", -50)
	}

	// Sticky affinity is a bonus after eligibility, not a hard pin.
	if cand.StickyMatch {
		base += StickyAffinityBonus
		add("sticky_affinity", StickyAffinityBonus)
	}

	// Utilization pressure can outweigh stickiness when the chosen server is
	// already busy or saturated.
	// Unknown or stale utilization is treated explicitly. Current policy is
	// neutral rather than a hidden zero-value bonus.
	if cand.EndpointSaturated {
		base -= 300
		add("utilization", -300)
	}
	if cand.EndpointLoad > 0 {
		loadPenalty := cand.EndpointLoad * 10
		if cand.EndpointLoadFresh {
			loadPenalty *= 2
		} else {
			loadPenalty += unknownUtilizationPenalty
		}
		if loadPenalty > 60 {
			loadPenalty = 60
		}
		base -= loadPenalty
		add("utilization", -loadPenalty)
	} else if !cand.EndpointLoadFresh {
		base -= unknownUtilizationPenalty
		add("utilization", -unknownUtilizationPenalty)
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
		add("deployment_locality", 15)
	}

	if cand.Power > 0 {
		base += float64(cand.Power) * 12
		add("power", float64(cand.Power)*12)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
		add("cost", -costPenalty)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
			add("cost", 15)
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
			add("quota_health", 15)
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
		add("power", 20)
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
		add("context_headroom", headroomBonus)
	}

	// Observation-derived perf bias.
	havePerfSignal := false
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		bonus := cand.ObservedTokensPerSec / 100.0
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		bonus := 1000.0 / cand.ObservedLatencyMS
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if !havePerfSignal {
		// Missing performance data is deliberate; current policy is neutral.
		base -= unknownPerformancePenalty
		add("performance", -unknownPerformancePenalty)
	}
	if cand.CostClass == "experimental" {
		base -= 75
		add("deployment_locality", -75)
	}

	// base tracks the implicit profile baseline so the components sum to the
	// same total as scorePolicy's legacy behavior.
	components["base"] = base - (components["cost"] + components["deployment_locality"] + components["quota_health"] + components["sticky_affinity"] + components["utilization"] + components["power"] + components["context_headroom"] + components["performance"])
	return components
}

package routing

import (
	"testing"
	"time"
)

func TestResolveStickyServerInstanceAcrossModelChanges(t *testing.T) {
	now := time.Date(2026, 5, 6, 12, 0, 0, 0, time.UTC)
	var stickyServerInstance string

	baseInputs := Inputs{
		Harnesses: []HarnessEntry{
			{
				Name:                "fiz",
				Surface:             "embedded-openai",
				CostClass:           "local",
				AutoRoutingEligible: true,
				Available:           true,
				ExactPinSupport:     true,
				SupportsTools:       true,
				Providers: []ProviderEntry{
					{
						Name:           "alpha",
						ServerInstance: "server-a",
						CostClass:      "local",
						DiscoveredIDs:  []string{"model-a", "model-b"},
						SupportsTools:  true,
					},
					{
						Name:           "beta",
						ServerInstance: "server-b",
						CostClass:      "local",
						DiscoveredIDs:  []string{"model-a", "model-b"},
						SupportsTools:  true,
					},
				},
			},
		},
		Now: now,
		EndpointLoadResolver: func(provider, endpoint, model string) (EndpointLoad, bool) {
			if provider != "alpha" && provider != "beta" {
				return EndpointLoad{}, false
			}
			switch model {
			case "model-a":
				switch endpoint {
				case "server-a":
					return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
				case "server-b":
					return EndpointLoad{NormalizedLoad: 1.0, UtilizationFresh: true}, true
				}
			case "model-b":
				switch endpoint {
				case "server-a":
					return EndpointLoad{NormalizedLoad: 1.0, UtilizationFresh: true}, true
				case "server-b":
					return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
				}
			}
			return EndpointLoad{}, false
		},
		StickyServerInstanceResolver: func(stickyKey string) (string, bool) {
			if stickyServerInstance == "" {
				return "", false
			}
			return stickyServerInstance, true
		},
	}

	first, err := Resolve(Request{Harness: "fiz", Model: "model-a", CorrelationID: "bead-lease-1"}, baseInputs)
	if err != nil {
		t.Fatalf("Resolve(model-a): %v", err)
	}
	if first.ServerInstance != "server-a" {
		t.Fatalf("first server_instance=%q, want server-a", first.ServerInstance)
	}
	if !first.Candidates[0].Eligible {
		t.Fatalf("first top candidate must be eligible: %#v", first.Candidates[0])
	}
	stickyServerInstance = first.ServerInstance

	second, err := Resolve(Request{Harness: "fiz", Model: "model-b", CorrelationID: "bead-lease-1"}, baseInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b with sticky lease): %v", err)
	}
	if second.ServerInstance != "server-a" {
		t.Fatalf("sticky decision server_instance=%q, want server-a", second.ServerInstance)
	}
	if second.Candidates[0].ServerInstance != "server-a" {
		t.Fatalf("sticky top candidate=%#v, want server-a", second.Candidates[0])
	}
	var sticky, nonSticky Candidate
	for _, c := range second.Candidates {
		switch c.ServerInstance {
		case "server-a":
			sticky = c
		case "server-b":
			nonSticky = c
		}
	}
	if sticky.ServerInstance != "server-a" || nonSticky.ServerInstance != "server-b" {
		t.Fatalf("second candidates=%#v, want both server-a and server-b", second.Candidates)
	}
	if nonSticky.Utilization >= sticky.Utilization {
		t.Fatalf("non-sticky utilization=%v, want lower than sticky utilization=%v", nonSticky.Utilization, sticky.Utilization)
	}
	if sticky.Score <= nonSticky.Score {
		t.Fatalf("sticky score=%.2f should beat the merely better non-sticky score=%.2f", sticky.Score, nonSticky.Score)
	}

	controlInputs := baseInputs
	controlInputs.StickyServerInstanceResolver = nil
	control, err := Resolve(Request{Harness: "fiz", Model: "model-b"}, controlInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b without sticky): %v", err)
	}
	if control.ServerInstance != "server-b" {
		t.Fatalf("control server_instance=%q, want server-b without sticky affinity", control.ServerInstance)
	}

	saturatedInputs := baseInputs
	saturatedInputs.StickyServerInstanceResolver = baseInputs.StickyServerInstanceResolver
	saturatedInputs.EndpointLoadResolver = func(provider, endpoint, model string) (EndpointLoad, bool) {
		if provider != "alpha" && provider != "beta" {
			return EndpointLoad{}, false
		}
		switch model {
		case "model-b":
			switch endpoint {
			case "server-a":
				return EndpointLoad{NormalizedLoad: 100, UtilizationFresh: true, UtilizationSaturated: true}, true
			case "server-b":
				return EndpointLoad{NormalizedLoad: 0.1, UtilizationFresh: true}, true
			}
		}
		return EndpointLoad{}, false
	}
	saturated, err := Resolve(Request{Harness: "fiz", Model: "model-b", CorrelationID: "bead-lease-1"}, saturatedInputs)
	if err != nil {
		t.Fatalf("Resolve(model-b with saturation): %v", err)
	}
	if saturated.ServerInstance != "server-b" {
		t.Fatalf("saturated decision server_instance=%q, want server-b because saturation outweighs sticky affinity", saturated.ServerInstance)
	}
	if saturated.Candidates[0].ServerInstance != "server-b" {
		t.Fatalf("saturated top candidate=%#v, want server-b", saturated.Candidates[0])
	}
	var saturatedSticky, saturatedNonSticky Candidate
	for _, c := range saturated.Candidates {
		switch c.ServerInstance {
		case "server-a":
			saturatedSticky = c
		case "server-b":
			saturatedNonSticky = c
		}
	}
	if !saturatedSticky.Eligible || !saturatedNonSticky.Eligible {
		t.Fatalf("saturated candidates must remain eligible for score comparison: %+v", saturated.Candidates)
	}
	if !saturatedSticky.ScoreComponents["utilization"] < 0 {
	}
	if saturatedSticky.Score >= saturatedNonSticky.Score {
		t.Fatalf("saturated sticky score=%.2f should lose to non-sticky score=%.2f", saturatedSticky.Score, saturatedNonSticky.Score)
	}
}

